	// Subscribe to one or more margin channels
	// Payload: SubscribeCommandPayload.
	// Content type: application/json.
	MessageSubscribeCommand = "subscribe"
	// Cancel one or more subscriptions
	// Payload: UnsubscribeCommandPayload.
	// Content type: application/json.
	MessageUnsubscribeCommand = "unsubscribe"
	// Add markets to an existing subscription
	// Payload: UpdateSubscriptionCommandPayload.
	// Content type: application/json.
	MessageUpdateSubscriptionCommand = "update_subscription_add"
	// Remove markets from an existing subscription
	// Payload: UpdateSubscriptionCommandPayload.
	// Content type: application/json.
	MessageUpdateSubscriptionDeleteCommand = "update_subscription_delete"
	// Update a subscription using `sid` rather than `sids`
	// Payload: UpdateSubscriptionCommandPayload.
	// Content type: application/json.
	MessageUpdateSubscriptionSingleSidCommand = "update_subscription_single_sid"
	// List all active subscriptions
	// Payload: ListSubscriptionsCommandPayload.
	// Content type: application/json.
	MessageListSubscriptionsCommand = "list_subscriptions"
	// Confirmation that subscription was successful
	// Payload: SubscribedResponsePayload.
	// Content type: application/json.
	MessageSubscribedResponse = "subscribed"
	// Confirmation that unsubscription was successful
	// Payload: UnsubscribedResponsePayload.
	// Content type: application/json.
